const SKU_PATTERN = /^[A-Z][A-Z0-9-]*$/;
const DIGITS_PATTERN = /^[0-9]+$/;

function parseSafeInteger(field, label, { allowZero }) {
  if (!DIGITS_PATTERN.test(field)) {
    throw new Error(`Invalid ${label}: ${JSON.stringify(field)}`);
  }
  const value = Number(field);
  if (!Number.isSafeInteger(value)) {
    throw new RangeError(`${label} exceeds Number.MAX_SAFE_INTEGER`);
  }
  if (!allowZero && value === 0) {
    throw new Error(`Invalid ${label}: must be positive`);
  }
  return value;
}

export function parseOrders(text) {
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }

  const orders = [];
  const lines = text.split('\n');

  for (const rawLine of lines) {
    const line = rawLine.replace(/\r$/, '');
    if (line.trim() === '') {
      continue;
    }

    const fields = line.split(',');
    if (fields.length !== 3) {
      throw new Error(`Malformed row: ${JSON.stringify(line)}`);
    }

    const sku = fields[0].trim();
    const quantityField = fields[1].trim();
    const unitPriceField = fields[2].trim();

    if (!SKU_PATTERN.test(sku)) {
      throw new Error(`Invalid SKU: ${JSON.stringify(sku)}`);
    }

    const quantity = parseSafeInteger(quantityField, 'quantity', { allowZero: false });
    const unitPriceCents = parseSafeInteger(unitPriceField, 'unitPriceCents', { allowZero: true });

    orders.push({ sku, quantity, unitPriceCents });
  }

  return orders;
}

const SKU_PATTERN = /^[A-Z][A-Z0-9-]*$/;
const DIGITS_PATTERN = /^[0-9]+$/;

function parseSafeInteger(field, label, { positive }) {
  if (!DIGITS_PATTERN.test(field)) {
    throw new Error(`Invalid ${label}: ${JSON.stringify(field)}`);
  }
  const value = Number(field);
  if (!Number.isSafeInteger(value)) {
    throw new RangeError(`${label} exceeds Number.MAX_SAFE_INTEGER`);
  }
  if (positive && value <= 0) {
    throw new Error(`Invalid ${label}: must be a positive integer`);
  }
  return value;
}

export function parseOrders(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseOrders expects a string');
  }

  const orders = [];
  const lines = text.split('\n');

  for (const rawLine of lines) {
    const line = rawLine.endsWith('\r') ? rawLine.slice(0, -1) : rawLine;
    if (line.trim() === '') {
      continue;
    }

    const fields = line.split(',');
    if (fields.length !== 3) {
      throw new Error(`Malformed row: ${JSON.stringify(line)}`);
    }

    const sku = fields[0].trim();
    const quantityField = fields[1].trim();
    const unitPriceField = fields[2].trim();

    if (!SKU_PATTERN.test(sku)) {
      throw new Error(`Invalid SKU: ${JSON.stringify(sku)}`);
    }

    const quantity = parseSafeInteger(quantityField, 'quantity', { positive: true });
    const unitPriceCents = parseSafeInteger(unitPriceField, 'unitPriceCents', { positive: false });

    orders.push({ sku, quantity, unitPriceCents });
  }

  return orders;
}

import { DEFAULT_OPTIONS } from './defaults.mjs';

const ALLOWED_KEYS = ['precision', 'prefix', 'unitLabel'];

export function resolveOptions(overrides = undefined) {
  if (overrides === undefined) {
    return { ...DEFAULT_OPTIONS };
  }

  if (overrides === null || typeof overrides !== 'object' || Array.isArray(overrides)) {
    throw new TypeError('overrides must be a plain object');
  }

  for (const key of Object.keys(overrides)) {
    if (!ALLOWED_KEYS.includes(key)) {
      throw new TypeError(`unknown option: ${key}`);
    }
  }

  const resolved = { ...DEFAULT_OPTIONS };

  if (Object.prototype.hasOwnProperty.call(overrides, 'precision')) {
    const precision = overrides.precision;
    if (typeof precision !== 'number' || !Number.isInteger(precision)) {
      throw new TypeError('precision must be an integer');
    }
    if (precision < 0 || precision > 4) {
      throw new RangeError('precision must be between 0 and 4');
    }
    resolved.precision = precision;
  }

  if (Object.prototype.hasOwnProperty.call(overrides, 'prefix')) {
    if (typeof overrides.prefix !== 'string') {
      throw new TypeError('prefix must be a string');
    }
    resolved.prefix = overrides.prefix;
  }

  if (Object.prototype.hasOwnProperty.call(overrides, 'unitLabel')) {
    if (typeof overrides.unitLabel !== 'string') {
      throw new TypeError('unitLabel must be a string');
    }
    resolved.unitLabel = overrides.unitLabel;
  }

  return resolved;
}

import { DEFAULT_OPTIONS } from './defaults.mjs';

const KNOWN_KEYS = ['precision', 'prefix', 'unitLabel'];

export function resolveOptions(overrides = {}) {
  if (overrides === undefined) {
    overrides = {};
  }

  if (overrides === null || typeof overrides !== 'object' || Array.isArray(overrides)) {
    throw new TypeError('overrides must be a plain object');
  }

  for (const key of Object.keys(overrides)) {
    if (!KNOWN_KEYS.includes(key)) {
      throw new TypeError(`Unknown option: ${key}`);
    }
  }

  const resolved = {
    precision: DEFAULT_OPTIONS.precision,
    prefix: DEFAULT_OPTIONS.prefix,
    unitLabel: DEFAULT_OPTIONS.unitLabel,
  };

  if (Object.prototype.hasOwnProperty.call(overrides, 'precision')) {
    const precision = overrides.precision;
    if (typeof precision !== 'number' || !Number.isInteger(precision)) {
      throw new TypeError('precision must be an integer');
    }
    if (precision < 0 || precision > 4) {
      throw new RangeError('precision must be between 0 and 4');
    }
    resolved.precision = precision;
  }

  if (Object.prototype.hasOwnProperty.call(overrides, 'prefix')) {
    const prefix = overrides.prefix;
    if (typeof prefix !== 'string') {
      throw new TypeError('prefix must be a string');
    }
    resolved.prefix = prefix;
  }

  if (Object.prototype.hasOwnProperty.call(overrides, 'unitLabel')) {
    const unitLabel = overrides.unitLabel;
    if (typeof unitLabel !== 'string') {
      throw new TypeError('unitLabel must be a string');
    }
    resolved.unitLabel = unitLabel;
  }

  return resolved;
}
